-- Function: public.fn_get_latest_media_consent_document
-- Backup generated on 2026-10-25 20:33:29

CREATE OR REPLACE FUNCTION public.fn_get_latest_media_consent_document(p_tenant_id uuid, p_child_id uuid)  RETURNS TABLE(id uuid, status character varying, document_title character varying, signed_at timestamp with time zone, withdrawn_at timestamp with time zone, declined_at timestamp with time zone, document_type character varying)  LANGUAGE plpgsql AS $function$ BEGIN     RETURN QUERY     SELECT d.id, d.status::VARCHAR, d.document_title::VARCHAR,            d.signed_at, d.withdrawn_at, d.declined_at,            COALESCE(t.document_type, '')::VARCHAR AS document_type     FROM child_consent_documents d     LEFT JOIN consent_templates t ON d.consent_template_id = t.id     WHERE d.tenant_id = p_tenant_id AND d.child_id = p_child_id       AND (t.document_type = 'PhotoVideoConsent' OR d.document_title ILIKE '%Photo%' OR d.document_title ILIKE '%Media%')     ORDER BY d.created_at DESC     LIMIT 1; END; $function$ ;
